      SUBROUTINE PLOTITCC     OUTPUTS LISTS OF MATRIX ELEMENTS FOR PLOTTINGCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'DEBUG.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM38A.CIN'      INCLUDE 'ELM38B.CIN'      INCLUDE 'ELM38C.CIN'      INCLUDE 'ELM38F.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'CC     LOCAL VARIABLESC      INTEGER         J, K, N, NLAY, NP1      LOGICAL         LAYOUT      REAL            ALF, COV, CORR, DALF, HMAX, HOR, PSI, VER,      1                VMAXC---------------------------------------------------------------------C      NANGS = 100      DEBUG = .FALSE.      NLAY = 0      DO 10 J = 1, NPLT      JCON = JPLOT(J)      KCON = KPLOT(J)      IF (JCON .EQ. 8 .AND. KCON .LE. 3) NLAY = NLAY + 1      CALL CONSTR      IF (FLUSHL) GO TO 500      QPLOT(J) = COC   10 CONTINUE      LAYOUT = NPLT .EQ. 2 .AND. NLAY .EQ. 2C      IF (LAYOUT) GO TO 100CC     PLOT OF PHASE ELLIPSEC      IF (NPLT .EQ. 2 .AND. EPLOT(1) .AND. EPLOT(2)) THEN        NP1 = NANGS + 1        DALF = 2.0*PI/FLOAT(NANGS)        IF (.NOT. RECENT) CALL BEAM        J = JPLOT(1)        K = KPLOT(2)        HMAX = SQRT(SIT(J,J))/UBEAM(J)        VMAX = SQRT(SIT(K,K))/UBEAM(K)        COV = SIT(J,K)/(UBEAM(J)*UBEAM(K))        CORR = COV/(HMAX*VMAX)        PSI = ASIN(CORR)        DO 60 N = 1, NP1        ALF = FLOAT(N-1)*DALF        HOR = HMAX*SIN(ALF)        VER = VMAX*COS(ALF-PSI)        WRITE (NPLOT,9008) HOR, VER   60   CONTINUECC     PLOT OF ANYTHING ELSEC     INCLUDING ANYTHING VS ACCUMULATED LENGTHC      ELSE        WRITE (NPLOT,9008) (QPLOT(J), J = 1, NPLT) 9008   FORMAT (8F10.5)      ENDIF      GO TO 300CC     BEAM LINE LAYOUTC  100 CALL PLTREF      IF (HIGH .EQ. 0.0 .OR. WIDE .EQ. 0.0) GO TO 500CC     RECTANGULARLY SHAPED BEAM LINE MAGNETC      IF (TYPED .EQ. 29) GO TO 200CC     VIEW FROM ABOVEC      IF (ND .EQ. 2) GO TO 150      CALL PLTRXZ      GO TO 300CC     VIEW FROM THE SIDEC  150 CALL PLTRYZ      GO TO 300CC     WEDGE BENDING MAGNETC  200 IF (ND .EQ. 1) THEN        CALL PLTSXZ      ELSE        CALL PLTSYZ      ENDIFC  300 PLNOW = .FALSE.C  500 RETURN      END